 p=argparse.ArgumentParser();p.add_argument('--parent',type=Path,required=True);p.add_argument('--platform',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();shutil.copytree(a.parent,a.output);changes={};rel='source/qdrv/compat/include/trace/ippkt.h';f=a.output/rel;t=f.read_text();anchor='#endif';idx=t.rfind(anchor);t=t[:idx]+'\n#define trace_ippkt_check trace_ippkt_check_tp\n#define trace_ippkt_dropped trace_ippkt_dropped_tp\n'+t[idx:];f.write_text(t,newline='\n');changes[rel]=sha(f);rel='source/qdrv/qdrv_tx.c';f=a.output/rel;t=f.read_text();t=t.replace('#include <net/sch_generic.h>','#include <net/sch_generic.h>\n#include <net/gso.h>',1);assert t.count('dev_deactivate(dev);')==1;t=t.replace('dev_deactivate(dev);','dev_deactivate(dev, true);',1);f.write_text(t,newline='\n');changes[rel]=sha(f);rel='providers/qtn_platform_support.c';f=a.output/rel;shutil.copyfile(a.platform/f.name,f);changes[rel]=sha(f);assert changes[rel]=='117e27ba5d10df0031d438adc4a2653d770d43bda0ab000ced20ce84e04be815';proof=json.loads((a.parent/'result.json').read_text());proof.update(status='SOURCE_ONLY_LINUX73_FULL44_TX_TRACE_GSO_QDISC_API_FIX',parent=str(a.parent),changed_sources=changes);proof['files']={str(x.relative_to(a.output)):sha(x)for group in('source','headers','kernel-overlay','providers')for x in(a.output/group).rglob('*')if x.is_file()};(a.output/'result.json').write_text(json.dumps(proof,indent=2)+'\n');print(json.dumps({'status':proof['status'],'changed_sources':changes},indent=2))
